 [Serializable]public sealed class CheckpointProof {public string Batch,SourceDirectory,RunId,ContentVersion,FinalRootPath,FinalRootSha256,ReportPath,ReportSha256,BatchManifestPath,BatchManifestSha256,PolicyMemoryPath,PolicyMemorySha256,ParentProofPath,ParentProofSha256,TracePath,TraceSha256;public FileProof[] Files;}
 private static string Hash(string p){using(var sha=SHA256.Create())using(var stream=File.OpenRead(p))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
 private static string CloneCheckpoint(string proofPath,string destination,out CheckpointProof proof,bool dateResume=false){
  proof=JsonUtility.FromJson<CheckpointProof>(File.ReadAllText(proofPath));Assert.That(proof.Batch,Is.Not.Null.And.Not.Empty);Assert.That(proof.RunId,Is.Not.Null.And.Not.Empty);
  Assert.That(Hash(proof.BatchManifestPath),Is.EqualTo(proof.BatchManifestSha256));
  Assert.That(new DirectoryInfo(Path.GetDirectoryName(proof.BatchManifestPath)).Name,Is.EqualTo(proof.Batch));
  var archive=JsonUtility.FromJson<ArchiveRows>("{\"rows\":"+File.ReadAllText(proof.BatchManifestPath)+"}").rows;
  foreach(var pair in new[]{new[]{proof.ReportPath,proof.ReportSha256},new[]{proof.FinalRootPath,proof.FinalRootSha256}})Assert.That(archive.Any(r=>r.verified&&r.sha256==pair[1]&&(Path.GetFullPath(r.archive)==Path.GetFullPath(pair[0])||Path.GetFullPath(r.source)==Path.GetFullPath(pair[0]))),Is.True,"Source evidence must belong to declared verified archive batch");
  Assert.That(Hash(proof.FinalRootPath),Is.EqualTo(proof.FinalRootSha256));Assert.That(Hash(proof.ReportPath),Is.EqualTo(proof.ReportSha256));
  Assert.That(File.ReadAllLines(proof.ReportPath).Contains(dateResume?"outcome=CoverageMissingByD85":"outcome=NaturalChampionD43"),Is.True,"Source batch must be a sealed natural champion continuation");
  string root=Path.GetFullPath(proof.SourceDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
  var actual=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Select(p=>p.Substring(root.Length).Replace('\\','/')).OrderBy(p=>p).ToArray();Assert.That(proof.Files.Select(f=>f.Path).OrderBy(p=>p).ToArray(),Is.EqualTo(actual),"Proof must list entire sealed save");Directory.CreateDirectory(destination);
  foreach(var f in proof.Files){string source=Path.GetFullPath(Path.Combine(root,f.Path));Assert.That(source.StartsWith(root,StringComparison.OrdinalIgnoreCase),Is.True);Assert.That(Hash(source),Is.EqualTo(f.Sha256));string output=Path.Combine(destination,f.Path);Directory.CreateDirectory(Path.GetDirectoryName(output));File.Copy(source,output,false);Assert.That(Hash(output),Is.EqualTo(f.Sha256));}
  return Hash(proofPath);
 }


 [Serializable]private sealed class ReplyRecord{public bool Accepted;public string Message;}
 private static void VerifyBound(CheckpointProof proof,string path,string hash){Assert.That(Hash(path),Is.EqualTo(hash));var rows=JsonUtility.FromJson<ArchiveRows>("{\"rows\":"+File.ReadAllText(proof.BatchManifestPath)+"}").rows;Assert.That(rows.Any(r=>r.verified&&r.sha256==hash&&(Path.GetFullPath(r.archive)==Path.GetFullPath(path)||Path.GetFullPath(r.source)==Path.GetFullPath(path))),Is.True,"Missing archive binding");}
 private static PolicyMemory RestoreDateMemory(CheckpointProof proof){
  VerifyBound(proof,proof.PolicyMemoryPath,proof.PolicyMemorySha256);VerifyBound(proof,proof.ParentProofPath,proof.ParentProofSha256);VerifyBound(proof,proof.TracePath,proof.TraceSha256);
  var report=File.ReadAllLines(proof.ReportPath);Assert.That(report,Does.Contain("sourceProofSha256="+proof.ParentProofSha256));Assert.That(report,Does.Contain("maxDay=85"));Assert.That(report,Does.Contain("strategy=public-romance-v3-sealed-d43"));
  var parent=JsonUtility.FromJson<CheckpointProof>(File.ReadAllText(proof.ParentProofPath));Assert.That(Hash(parent.BatchManifestPath),Is.EqualTo(parent.BatchManifestSha256));VerifyBound(parent,parent.FinalRootPath,parent.FinalRootSha256);VerifyBound(parent,parent.ReportPath,parent.ReportSha256);Assert.That(File.ReadAllLines(parent.ReportPath),Does.Contain("outcome=NaturalChampionD43"));Assert.That(File.ReadAllLines(parent.ReportPath),Does.Contain("contest=ThinBuild"));Assert.That(parent.RunId,Is.EqualTo(proof.RunId));Assert.That(report,Does.Contain("sourceBatch="+parent.Batch));
  var m=JsonUtility.FromJson<PolicyMemory>(File.ReadAllText(proof.PolicyMemoryPath));Assert.That(m.RunId,Is.EqualTo(proof.RunId));Assert.That(m.Seed,Is.EqualTo(1u));Assert.That(m.StrategyVersion,Is.EqualTo("public-romance-v3-sealed-d43"));Assert.That(m.PendingOperation,Is.Empty);Assert.That(report,Does.Contain("businessCommands="+m.LastOperation));
  var accepted=new System.Collections.Generic.Dictionary<string,FrontendAction>();FrontendAction pending=null,last=null;
  foreach(string line in File.ReadLines(proof.TracePath)){if(line.StartsWith("{\"OperationId\":")){pending=JsonUtility.FromJson<FrontendAction>(line);}else if(line.StartsWith("{\"Accepted\":")){var reply=JsonUtility.FromJson<ReplyRecord>(line);Assert.That(pending,Is.Not.Null);Assert.That(reply.Accepted,Is.True,"Ambiguous source command is not a date-only seam");accepted[pending.OperationId]=pending;last=pending;pending=null;}}
  Assert.That(pending,Is.Null);Assert.That(last,Is.Not.Null);Assert.That(last.OperationId.EndsWith("/"+m.LastOperation),Is.True);Assert.That(last.ActionId,Is.EqualTo("next-day"));Assert.That(accepted.Count,Is.EqualTo(m.LastOperation));Assert.That(accepted.Values.All(a=>a.RunId==m.RunId),Is.True);
  Assert.That(accepted.Values.Count(a=>a.ActionId=="rel-dialogue"),Is.EqualTo(m.Dialogues));Assert.That(accepted.Values.Count(a=>a.ActionId=="rel-gift"),Is.EqualTo(m.Gifts));Assert.That(accepted.Values.Count(a=>a.ActionId=="rel-confess"),Is.EqualTo(m.Confessions));Assert.That(accepted.Values.Count(a=>a.ActionId=="shop-buy")-m.Gifts,Is.EqualTo(m.Books));Assert.That(accepted.Values.Any(a=>a.ActionId=="rel-invite"),Is.EqualTo(m.Invited));Assert.That(accepted.Values.Any(a=>a.ActionId=="competition-enroll"),Is.EqualTo(m.Enrolled));
  Assert.That(accepted.Values.Any(a=>a.ActionId=="save-plan"&&JsonUtility.FromJson<PlanDraft>(a.StringValue).Slots.All(slot=>slot.AnchorId=="evening")),Is.EqualTo(m.EveningPlan));return m;
 }
 private static string HistoryRecord(AchievementHistoryEntry h)=>JsonUtility.ToJson(h.Snapshot)+"\n"+h.NoteState+"\n"+h.Note;
 private const string StrategyVersion="public-romance-v2-explicit-seed";
 private sealed class EvidenceTrace:IDisposable {
  private readonly StreamWriter writer; private readonly System.Collections.Generic.HashSet<string> views=new System.Collections.Generic.HashSet<string>();
  public long Bytes,ViewReferences; public const long Limit=268435456;
  public EvidenceTrace(string path){writer=new StreamWriter(path,false,new System.Text.UTF8Encoding(false));}
  public void WriteLine(string line){if(line.StartsWith("{\"RunId\":")&&line.Contains("\"ScreenId\":")){string hash=ContentHash.Sha256(line);if(!views.Add(hash)){line="{\"viewRef\":\""+hash+"\"}";ViewReferences++;}else line="{\"viewHash\":\""+hash+"\",\"view\":"+line+"}";}long bytes=System.Text.Encoding.UTF8.GetByteCount(line+writer.NewLine);if(Bytes+bytes>Limit)throw new InvalidOperationException("EvidenceByteBudgetExceeded");writer.WriteLine(line);Bytes+=bytes;}
  public void Dispose()=>writer.Dispose();
 }

 private static void AuditPublicProbability(GameSession session){
  var option=session.ReadView().Actions.Single(a=>a.Id=="rel-confess");
  var shown=Regex.Match(option.Label??"",@"成功率\s+(?<probability>\d+(?:\.\d+)?)%");Assert.That(shown.Success,Is.True,"Missing public probability");
  var snapshot=JsonUtility.FromJson<ConfessionSnapshot>(session.InspectSnapshot().FindFragment("confession-snapshot","player").Json);
  string expected=(snapshot.ProbabilityThousandths/10m).ToString("0.0",System.Globalization.CultureInfo.InvariantCulture);
  Assert.That(shown.Groups["probability"].Value,Is.EqualTo(expected));
  Assert.That(decimal.Parse(shown.Groups["probability"].Value,System.Globalization.CultureInfo.InvariantCulture),Is.EqualTo(snapshot.ProbabilityThousandths/10m));
 }
