 private static PlanDraft Plan(bool evening){string[] actions={"bench_press","dumbbell_curl","lat_pulldown","triceps_pushdown","squat","hip_thrust","shoulder_press","lateral_raise"};if(evening)return new PlanDraft{Mode=PlanMode.DayCycle,Slots=actions.Select((id,i)=>{var s=PlanCatalog.Training(i,TrainingCombination.Free,id);s.Volume=TrainingVolume.Low;s.AnchorId="evening";return s;}).ToArray()};return new PlanDraft{Mode=PlanMode.NaturalWeek,Slots=Enumerable.Range(0,7).Select(i=>{if(i!=0&&i!=2&&i!=5)return PlanCatalog.Rest(i);var s=PlanCatalog.Training(i,TrainingCombination.Free,actions[i]);s.Volume=TrainingVolume.Low;return s;}).ToArray()};}
