 private void RunRelationshipRoute(bool continuation,bool dateResume=false){
  string strategy=continuation?"public-romance-v3-sealed-d43":StrategyVersion;

  string seedText=continuation?"1":Environment.GetEnvironmentVariable("FITNESS_ROMANCE_SEED")??"1";uint seed;if(!uint.TryParse(seedText,System.Globalization.NumberStyles.None,System.Globalization.CultureInfo.InvariantCulture,out seed)||seed==0)throw new ArgumentOutOfRangeException("FITNESS_ROMANCE_SEED","Expected positive UInt32 seed 1..4294967295");
  bool longRun=continuation||Environment.GetEnvironmentVariable("FITNESS_ROMANCE_LONG")=="1";int seconds=continuation?2400:longRun?int.Parse(Environment.GetEnvironmentVariable("FITNESS_ROMANCE_SECONDS")??throw new InvalidOperationException("Explicit long budget required")):600;Assert.That(seconds,Is.InRange(1,7200));int maxDay=dateResume?127:continuation?85:longRun?43:8;
  string dir=Path.Combine(Path.GetTempPath(),"Fitness-Natural-Romance",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);CheckpointProof sourceProof=null;string sourceProofHash="",sourcePermanent="";var preservedHistory=new System.Collections.Generic.Dictionary<string,string>();var sourceHistory=new System.Collections.Generic.List<AchievementHistoryEntry>();
  if(continuation){string proofPath=Environment.GetEnvironmentVariable(dateResume?"FITNESS_ROMANCE_DATE_PROOF":"FITNESS_ROMANCE_CONTINUATION_PROOF");Assert.That(File.Exists(proofPath),Is.True,"Sealed D43 proof required");sourceProofHash=CloneCheckpoint(proofPath,Path.Combine(dir,"save"),out sourceProof,dateResume);if(!dateResume)Assert.That(File.ReadAllLines(sourceProof.ReportPath),Does.Contain("contest=ThinBuild"));Assert.That(File.ReadAllLines(sourceProof.ReportPath),Does.Contain("seed=1"));File.Copy(proofPath,Path.Combine(dir,"source-proof.json"));using(var store=new LocalCheckpointStore(Path.Combine(dir,"save"),new UnityJsonStateCodec())){store.Load();sourceHistory=new EndingProgression(new UnityJsonStateCodec()).ReadHistory(store,0,64);}foreach(var entry in sourceHistory)preservedHistory.Add(entry.Snapshot.AchievementId,HistoryRecord(entry));}
  var memory=dateResume?RestoreDateMemory(sourceProof):new PolicyMemory{Seed=seed,StrategyVersion=strategy};int sourceLastOperation=dateResume?memory.LastOperation:0;if(dateResume){File.Copy(sourceProof.PolicyMemoryPath,Path.Combine(dir,"source-policy-memory.json"));File.Copy(sourceProof.ParentProofPath,Path.Combine(dir,"parent-proof.json"));}var s=GameSession.OpenAutomation(Path.Combine(dir,"save"),seed);var watch=Stopwatch.StartNew();int command=0,day=dateResume?85:continuation?43:1,checkedMenu=0,input=0,clocks=0;int successOrdinal=0,successContestDay=0,successAttendance=0;int recoveries=0;FrontendAction lastCommand=null;bool needsRest=false,publicRomanceEnding=false;string routeStage="AwaitDialogue";string outcome="BudgetExhausted",error="";string firstLeanGrantJson=null;var observedOtherAchievements=new System.Collections.Generic.HashSet<string>();
  string operationPrefix=continuation?"romance-continuation/"+Guid.NewGuid().ToString("N")+"/":"romance/";bool initialContinuationPlanSaved=dateResume||!continuation;
  if(continuation){var root=s.InspectSnapshot();Assert.That(JsonUtility.ToJson(root),Is.EqualTo(JsonUtility.ToJson(JsonUtility.FromJson<RootEnvelope>(File.ReadAllText(sourceProof.FinalRootPath)))));Assert.That(root.RunId,Is.EqualTo(sourceProof.RunId));Assert.That(JsonUtility.FromJson<SessionState>(root.FindFragment("session","player").Json).Day,Is.EqualTo(dateResume?85:43));var competition=JsonUtility.FromJson<CompetitionState>(root.FindFragment("competition","player").Json);if(!dateResume){Assert.That(competition.Current.Ordinal,Is.EqualTo(2));Assert.That(competition.Current.ActualAttendanceCount,Is.Zero);Assert.That(competition.Current.Facts,Is.Empty);}else{var previous=competition.Editions.Single(e=>e.Ordinal==2);Assert.That(previous.ContestDay,Is.EqualTo(84));Assert.That(previous.ActualAttendanceCount,Is.GreaterThan(0));Assert.That(previous.Facts.Any(f=>f.Kind==CompetitionFactKind.Champion),Is.True);Assert.That(previous.Facts.Any(f=>f.Kind==CompetitionFactKind.NonChampion||f.Kind==CompetitionFactKind.Unfulfilled),Is.False);Assert.That(JsonUtility.FromJson<RelationshipState>(root.FindFragment("relationships","player").Json).RomanceEstablished,Is.False);}var progress=JsonUtility.FromJson<ProgressionRun>(root.FindFragment("progression","player").Json);Assert.That(progress.TerminalLock,Is.False);Assert.That(progress.HasActive,Is.False);sourcePermanent=root.PermanentFragments.Single(f=>f.Owner=="progression"&&f.Scope=="permanent").Json;var grant=JsonUtility.FromJson<ProgressionPermanent>(sourcePermanent).TemplateGrants.Single(g=>g.TemplateId=="lean_social");var prior=sourceHistory.Single(h=>h.Snapshot.AchievementId==grant.AchievementId);Assert.That(prior.Snapshot.RunId,Is.EqualTo(root.RunId));Assert.That(prior.Snapshot.EndingId,Is.EqualTo("lean_champion"));Assert.That(prior.Snapshot.Terminal,Is.False);firstLeanGrantJson=JsonUtility.ToJson(grant);observedOtherAchievements.Add(grant.AchievementId);File.WriteAllText(Path.Combine(dir,"source-history.txt"),string.Join("\n",sourceHistory.Select(HistoryRecord)));}

