   Action<FrontendOption> send=o=>{var v=s.ReadView();var a=new FrontendAction{OperationId=operationPrefix+(++command),RunId=v.RunId,ExpectedRevision=v.Revision,ActionId=o.Id,StringValue=o.StringValue,IntValue=o.IntValue};log.WriteLine(JsonUtility.ToJson(v));log.WriteLine(JsonUtility.ToJson(a));lastCommand=a;memory.PendingOperation=a.OperationId;memory.LastOperation=sourceLastOperation+command;File.WriteAllText(Path.Combine(dir,"policy-memory.json"),JsonUtility.ToJson(memory,true));var r=s.Execute(a);log.WriteLine(JsonUtility.ToJson(r));if(!r.Accepted){var retry=s.ReadView().Actions.FirstOrDefault(x=>x.Enabled&&x.Id=="retry-storage");if(retry!=null){var rv=s.ReadView();var retryCommand=new FrontendAction{OperationId=operationPrefix+"retry/"+(++command),RunId=rv.RunId,ExpectedRevision=rv.Revision,ActionId=retry.Id,StringValue=retry.StringValue,IntValue=retry.IntValue};log.WriteLine(JsonUtility.ToJson(rv));log.WriteLine(JsonUtility.ToJson(retryCommand));var rr=s.Execute(retryCommand);log.WriteLine(JsonUtility.ToJson(rr));if(rr.Accepted){r=s.Execute(a);log.WriteLine(JsonUtility.ToJson(a));log.WriteLine(JsonUtility.ToJson(r));}}if(!r.Accepted)throw new InvalidOperationException("CommandNotConfirmed: stop local accounting; "+r.Message);} memory.PendingOperation="";if(continuation&&o.Id=="competition-enroll"){var contestDay=Regex.Match(v.Body??"",@"薄肌\s*·\s*第\s*(\d+)\s*日");Assert.That(contestDay.Success,Is.True,"Missing public contest date");memory.RegisteredContestDay=int.Parse(contestDay.Groups[1].Value);}if(o.Id=="rel-confess"){memory.LastConfessionReply=r.Message??"";if(memory.LastConfessionReply.Contains("再相处")){memory.LastFailureDay=day;routeStage="ConfessionFailedCooldown";}else routeStage="ConfessionSubmitted";} };
   Action saveMemory=()=>{memory.RunId=s.ReadView().RunId;memory.LastOperation=sourceLastOperation+command;File.WriteAllText(Path.Combine(dir,"policy-memory.json"),JsonUtility.ToJson(memory,true));};
   Action restart=()=>{string before=JsonUtility.ToJson(s.InspectSnapshot());s.Dispose();s=GameSession.OpenAutomation(Path.Combine(dir,"save"),seed);Assert.That(JsonUtility.ToJson(s.InspectSnapshot()),Is.EqualTo(before));recoveries++;var restored=JsonUtility.FromJson<PolicyMemory>(File.ReadAllText(Path.Combine(dir,"policy-memory.json")));Assert.That(restored.Seed,Is.EqualTo(seed));Assert.That(restored.StrategyVersion,Is.EqualTo(strategy));Assert.That(restored.RunId,Is.EqualTo(s.ReadView().RunId));Assert.That(restored.LastOperation,Is.EqualTo(memory.LastOperation));Assert.That(restored.PendingOperation,Is.Empty);Assert.That(JsonUtility.ToJson(restored),Is.EqualTo(JsonUtility.ToJson(memory)));memory=restored;var resume=s.ReadView().Actions.FirstOrDefault(a=>a.Enabled&&a.Id=="continue-game");if(resume!=null){send(resume);saveMemory();}};
   try{for(int step=0;step<500000&&watch.Elapsed.TotalSeconds<seconds;step++){
    var v=s.ReadView();var options=v.Actions.Where(a=>a.Enabled).ToArray();var dayMatch=Regex.Match(v.Status??"",@"第\s*(\d+)\s*日");if(dayMatch.Success)day=int.Parse(dayMatch.Groups[1].Value);Assert.That(day,Is.LessThanOrEqualTo(maxDay),"CoverageMissing by date budget");
    if(continuation&&day>=maxDay){outcome="CoverageMissingByD"+maxDay;break;}
    if(day!=memory.LastObservedDay||v.ScreenId.StartsWith("summary/")){needsRest=false;memory.LastObservedDay=day;}
    if(v.ScreenId.StartsWith("ending-")&&(v.Title??"").Contains("恋爱成功"))publicRomanceEnding=true;
    Assert.That(v.ScreenId,Is.Not.EqualTo("error"),v.Body);
    if(v.TrainingInput!=null){Assert.That(PublicEightInputDriver.DriveActiveSet(s,v.TrainingInput.ExerciseId,line=>{if(watch.Elapsed.TotalSeconds>=seconds)throw new InvalidOperationException("GlobalBudget");if(line.StartsWith("advance-ms="))clocks++;if(line.Contains("\"ActionId\":\"training-input\""))input++;log.WriteLine(line);}),Is.EqualTo("AwaitProductionResult"));continue;}
