    if(continuation&&!initialContinuationPlanSaved&&options.Any(a=>a.Id=="save-plan")){Assert.That(day,Is.EqualTo(43),"Missing D43 plan-edit window");var beforePlan=JsonUtility.FromJson<PlanStateRecord>(s.InspectSnapshot().FindFragment("plan","player").Json);var fixedFragments=s.InspectSnapshot().Fragments.Where(f=>f.Scope=="player"&&(f.Owner=="flow"||f.Owner=="training")).ToDictionary(f=>f.Owner,f=>f.Json);o=options.First(a=>a.Id=="save-plan");o.StringValue=JsonUtility.ToJson(Plan(false));send(o);var saved=JsonUtility.FromJson<PlanStateRecord>(s.InspectSnapshot().FindFragment("plan","player").Json);Assert.That(saved.HasPending,Is.True);Assert.That(saved.Pending.EffectiveDay,Is.EqualTo(44));Assert.That(JsonUtility.ToJson(saved.Active),Is.EqualTo(JsonUtility.ToJson(beforePlan.Active)));foreach(var entry in fixedFragments)Assert.That(s.InspectSnapshot().FindFragment(entry.Key,"player").Json,Is.EqualTo(entry.Value));initialContinuationPlanSaved=true;saveMemory();continue;}
