    foreach(string id in new[]{"ending-segment","ending-empty","ending-continue","settle","continue","shop-leave","item-use","next-day"})if(o==null)o=options.FirstOrDefault(a=>a.Id==id);
    if(o!=null&&o.Id=="ending-continue"){
     var root=s.InspectSnapshot();var progression=JsonUtility.FromJson<ProgressionRun>(root.FindFragment("progression","player").Json);if(publicRomanceEnding){Assert.That(progression.Active.EndingId,Is.EqualTo("romance_success"));var successEdition=JsonUtility.FromJson<CompetitionState>(root.FindFragment("competition","player").Json).Current;successOrdinal=successEdition.Ordinal;successContestDay=successEdition.ContestDay;successAttendance=successEdition.ActualAttendanceCount;}Assert.That(progression.TerminalLock,Is.False);string achievement=progression.Active.AchievementId;     var permanentFragment=root.PermanentFragments.SingleOrDefault(f=>f.Owner=="progression"&&f.Scope=="permanent");
     var grantState=permanentFragment==null?new ProgressionPermanent():JsonUtility.FromJson<ProgressionPermanent>(permanentFragment.Json);
     var leanGrants=grantState.TemplateGrants.Where(g=>g.TemplateId=="lean_social").ToArray();Assert.That(leanGrants.Length,Is.LessThanOrEqualTo(1));
     bool hadPriorLeanGrant=firstLeanGrantJson!=null;
     if(hadPriorLeanGrant){Assert.That(leanGrants.Length,Is.EqualTo(1));Assert.That(JsonUtility.ToJson(leanGrants[0]),Is.EqualTo(firstLeanGrantJson));}
     if(publicRomanceEnding){Assert.That(leanGrants.Length,Is.EqualTo(1));if(!hadPriorLeanGrant)Assert.That(leanGrants[0].AchievementId,Is.EqualTo(achievement));else Assert.That(observedOtherAchievements.Contains(leanGrants[0].AchievementId),Is.True,"Prior grant must have an observed real success");}
     if(firstLeanGrantJson==null&&leanGrants.Length==1){firstLeanGrantJson=JsonUtility.ToJson(leanGrants[0]);File.WriteAllText(Path.Combine(dir,"first-observed-lean-grant.json"),firstLeanGrantJson);}
     var normal=root.Fragments.Where(f=>f.Owner!="progression").ToDictionary(f=>f.Owner.Length+":"+f.Owner+f.Scope.Length+":"+f.Scope,f=>JsonUtility.ToJson(f));
     send(o);saveMemory();var completed=lastCommand;string committed=JsonUtility.ToJson(s.InspectSnapshot());Assert.That(s.Execute(completed).Accepted,Is.True);Assert.That(JsonUtility.ToJson(s.InspectSnapshot()),Is.EqualTo(committed));
     Assert.That(s.InspectSnapshot().Fragments.Count(f=>f.Owner!="progression"),Is.EqualTo(normal.Count));foreach(var f in s.InspectSnapshot().Fragments.Where(f=>f.Owner!="progression"))Assert.That(JsonUtility.ToJson(f),Is.EqualTo(normal[f.Owner.Length+":"+f.Owner+f.Scope.Length+":"+f.Scope]));
     if(publicRomanceEnding)Assert.That(JsonUtility.FromJson<RelationshipState>(s.InspectSnapshot().FindFragment("relationships","player").Json).RomanceEstablished,Is.True);
     s.Dispose();using(var store=new LocalCheckpointStore(Path.Combine(dir,"save"),new UnityJsonStateCodec())){store.Load();var history=new EndingProgression(new UnityJsonStateCodec()).ReadHistory(store,0,64);foreach(var entry in preservedHistory)Assert.That(HistoryRecord(history.Single(h=>h.Snapshot.AchievementId==entry.Key)),Is.EqualTo(entry.Value));Assert.That(history.Count(h=>h.Snapshot.AchievementId==achievement),Is.EqualTo(1));if(publicRomanceEnding)Assert.That(history.Count(h=>h.Snapshot.RunId==root.RunId&&h.Snapshot.EndingId=="romance_success"),Is.EqualTo(1));if(leanGrants.Length==1){var source=history.Single(h=>h.Snapshot.AchievementId==leanGrants[0].AchievementId);Assert.That(source.Snapshot.RunId,Is.EqualTo(root.RunId));Assert.That(new[]{"lean_champion","romance_success"}.Contains(source.Snapshot.EndingId),Is.True);Assert.That(source.Snapshot.Terminal,Is.False);}if(!publicRomanceEnding)observedOtherAchievements.Add(achievement);}
     s=GameSession.OpenAutomation(Path.Combine(dir,"save"),seed);Assert.That(JsonUtility.ToJson(s.InspectSnapshot()),Is.EqualTo(committed));recoveries++;var restored=JsonUtility.FromJson<PolicyMemory>(File.ReadAllText(Path.Combine(dir,"policy-memory.json")));Assert.That(restored.Seed,Is.EqualTo(seed));Assert.That(restored.StrategyVersion,Is.EqualTo(strategy));Assert.That(restored.RunId,Is.EqualTo(s.ReadView().RunId));Assert.That(restored.LastOperation,Is.EqualTo(memory.LastOperation));Assert.That(restored.PendingOperation,Is.Empty);Assert.That(JsonUtility.ToJson(restored),Is.EqualTo(JsonUtility.ToJson(memory)));memory=restored;var resume=s.ReadView().Actions.FirstOrDefault(a=>a.Enabled&&a.Id=="continue-game");if(resume!=null)send(resume);if(publicRomanceEnding){if(continuation)Assert.That(s.InspectSnapshot().PermanentFragments.Single(f=>f.Owner=="progression"&&f.Scope=="permanent").Json,Is.EqualTo(sourcePermanent));outcome="NaturalRomanceContinued";break;}publicRomanceEnding=false;routeStage="OtherSuccessContinuedCompetitionStillRequired";continue;
    }
    if(o!=null){if(o.Id=="rel-confess"){if(memory.FirstConfessionDay==0)memory.FirstConfessionDay=day;memory.LastProbability=o.Label;routeStage=memory.Confessions==0?"FirstConfession":"RetryConfession";}send(o);if(o.Id=="rel-confession-preview")AuditPublicProbability(s);if(o.Id=="settle")needsRest=true;if(o.Id=="rel-invite")memory.Invited=true;if(o.Id=="shop-buy"){memory.Books++;routeStage=memory.LastFailureDay>0?"ReplacementGiftPurchased":"GiftPurchased";}if(o.Id=="rel-gift"){memory.Books--;memory.Gifts++;}if(o.Id=="competition-enroll")memory.Enrolled=true;if(o.Id=="rel-confess")memory.Confessions++;saveMemory();if(new[]{"rel-invite","shop-buy","rel-gift","rel-confession-preview","rel-confess","ending-segment","ending-empty"}.Contains(o.Id))restart();}
    else{if(memory.LastFailureDay>0&&day<memory.LastFailureDay+8)routeStage="Cooldown";else routeStage="WaitingForPublicEntry";var unknown=options.FirstOrDefault(a=>!new[]{"save-plan","open-menu","competition-menu","rel-teach","rel-dialogue","rel-gift","rel-invite"}.Contains(a.Id));Assert.That(unknown,Is.Null,"MissingHandler: "+v.ScreenId+"/"+unknown?.Id);log.WriteLine("advance-ms=0");clocks++;s.Advance(0);}
   }Assert.That(outcome,Is.EqualTo(longRun?"NaturalRomanceContinued":"DialogueInteractionPreflight"));}
   catch(Exception ex){error=ex.ToString();throw;}
   finally{File.WriteAllText(Path.Combine(dir,"final.json"),JsonUtility.ToJson(s.InspectSnapshot(),true));File.WriteAllText(Path.Combine(dir,"report.txt"),"strategy="+strategy+"\nsegment="+(dateResume?"sealed-d85-once":"original-entry")+"\nsourceLastOperation="+sourceLastOperation+"\npolicyLastOperation="+memory.LastOperation+"\npolicyDialogues="+memory.Dialogues+"\npolicyGifts="+memory.Gifts+"\npolicyConfessions="+memory.Confessions+"\nsourceBatch="+(sourceProof==null?"":sourceProof.Batch)+"\nsourceProofSha256="+sourceProofHash+"\nseed="+seed.ToString(System.Globalization.CultureInfo.InvariantCulture)+"\nsuccessOrdinal="+successOrdinal+"\nsuccessContestDay="+successContestDay+"\nsuccessAttendance="+successAttendance+"\nmaxSteps=500000\nmaxDay="+maxDay+"\nmaxSeconds="+seconds+"\nseconds="+watch.Elapsed.TotalSeconds+"\nbusinessCommands="+command+"\ninputCommands="+input+"\nclockCalls="+clocks+"\nrecoveries="+recoveries+"\nevidenceBytes="+log.Bytes+"\nevidenceByteLimit="+EvidenceTrace.Limit+"\nviewReferences="+log.ViewReferences+"\nmode="+(longRun?"natural-romance":"dialogue-preflight")+"\ncoverageClassification="+(outcome=="DialogueInteractionPreflight"?"DialogueOnly":outcome=="NaturalRomanceContinued"?"NaturalRomance":"RouteNotReachedNotProductDefect")+"\nfirstConfessionDay="+memory.FirstConfessionDay+"\nrouteStage="+routeStage+"\nlastFailureDay="+memory.LastFailureDay+"\nlastProbability="+memory.LastProbability+"\nlastConfessionReply="+memory.LastConfessionReply+"\noutcome="+outcome+"\nexception="+error);s.Dispose();TestContext.WriteLine(dir);}
  }
 }
}
